"use client";

import React, { useRef, useState, useCallback, useEffect } from "react";
import Image from "next/image";

interface LogoItem {
  src: string;
  alt: string;
  size?: "normal" | "large";
}

interface MarqueeProps {
  items?: string[];
  logos?: LogoItem[];
  direction?: 1 | -1;
  speed?: number;
}

export const Marquee: React.FC<MarqueeProps> = ({ items, logos, direction = 1, speed = 30 }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [startX, setStartX] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);
  const [dragOffset, setDragOffset] = useState(0);

  // Handle mouse down
  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      setIsDragging(true);
      setStartX(e.pageX);
      setScrollLeft(dragOffset);
    },
    [dragOffset]
  );

  // Handle touch start
  const handleTouchStart = useCallback(
    (e: React.TouchEvent) => {
      setIsDragging(true);
      setStartX(e.touches[0].pageX);
      setScrollLeft(dragOffset);
    },
    [dragOffset]
  );

  // Handle mouse move
  const handleMouseMove = useCallback(
    (e: React.MouseEvent) => {
      if (!isDragging) return;
      e.preventDefault();
      const x = e.pageX;
      const walk = (x - startX) * 2;
      setDragOffset(scrollLeft + walk);
    },
    [isDragging, startX, scrollLeft]
  );

  // Handle touch move
  const handleTouchMove = useCallback(
    (e: React.TouchEvent) => {
      if (!isDragging) return;
      const x = e.touches[0].pageX;
      const walk = (x - startX) * 2;
      setDragOffset(scrollLeft + walk);
    },
    [isDragging, startX, scrollLeft]
  );

  // Handle drag end
  const handleDragEnd = useCallback(() => {
    setIsDragging(false);
  }, []);

  // Global mouse up listener
  useEffect(() => {
    const handleGlobalMouseUp = () => {
      if (isDragging) {
        setIsDragging(false);
      }
    };

    window.addEventListener("mouseup", handleGlobalMouseUp);
    window.addEventListener("touchend", handleGlobalMouseUp);

    return () => {
      window.removeEventListener("mouseup", handleGlobalMouseUp);
      window.removeEventListener("touchend", handleGlobalMouseUp);
    };
  }, [isDragging]);

  // If logos are provided, use logo mode
  if (logos && logos.length > 0) {
    return (
      <div
        ref={containerRef}
        className="relative flex overflow-hidden border-y-4 border-neo-border bg-neo-surface py-6 select-none cursor-grab active:cursor-grabbing"
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleDragEnd}
        onMouseLeave={handleDragEnd}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleDragEnd}
      >
        <div
          className="flex"
          style={{
            transform: `translateX(${dragOffset}px)`,
            transition: isDragging ? "none" : "transform 0.3s ease-out",
          }}
        >
          <div
            className={`flex ${isDragging ? "" : "animate-marquee"}`}
            style={{
