"use client";

import React, { useRef, useState, useCallback, useEffect } from "react";
import Image from "next/image";

interface LogoItem {
  src: string;
  alt: string;
  size?: "normal" | "large";
}

interface MarqueeProps {
  items?: string[];
  logos?: LogoItem[];
  direction?: 1 | -1;
  speed?: number;
}

export const Marquee: React.FC<MarqueeProps> = ({ items, logos, direction = 1, speed = 30 }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [startX, setStartX] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);
  const [dragOffset, setDragOffset] = useState(0);

  // Handle mouse down
  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      setIsDragging(true);
      setStartX(e.pageX);
      setScrollLeft(dragOffset);
    },
    [dragOffset]
  );

  // Handle touch start
  const handleTouchStart = useCallback(
    (e: React.TouchEvent) => {
      setIsDragging(true);
      setStartX(e.touches[0].pageX);
      setScrollLeft(dragOffset);
    },
    [dragOffset]
  );

  // Handle mouse move
  const handleMouseMove = useCallback(
    (e: React.MouseEvent) => {
      if (!isDragging) return;
      e.preventDefault();
      const x = e.pageX;
      const walk = (x - startX) * 2;
      setDragOffset(scrollLeft + walk);
    },
    [isDragging, startX, scrollLeft]
  );

  // Handle touch move
  const handleTouchMove = useCallback(
    (e: React.TouchEvent) => {
      if (!isDragging) return;
      const x = e.touches[0].pageX;
      const walk = (x - startX) * 2;
      setDragOffset(scrollLeft + walk);
    },
    [isDragging, startX, scrollLeft]
  );

  // Handle drag end
  const handleDragEnd = useCallback(() => {
    setIsDragging(false);
  }, []);

  // Global mouse up listener
  useEffect(() => {
    const handleGlobalMouseUp = () => {
      if (isDragging) {
        setIsDragging(false);
      }
    };

    window.addEventListener("mouseup", handleGlobalMouseUp);
    window.addEventListener("touchend", handleGlobalMouseUp);

    return () => {
      window.removeEventListener("mouseup", handleGlobalMouseUp);
      window.removeEventListener("touchend", handleGlobalMouseUp);
    };
  }, [isDragging]);

  // If logos are provided, use logo mode
  if (logos && logos.length > 0) {
    return (
      <div
        ref={containerRef}
        className="relative flex overflow-hidden border-y-4 border-neo-border bg-neo-surface py-6 select-none cursor-grab active:cursor-grabbing"
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleDragEnd}
        onMouseLeave={handleDragEnd}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleDragEnd}
      >
        <div
          className="flex"
          style={{
            transform: `translateX(${dragOffset}px)`,
            transition: isDragging ? "none" : "transform 0.3s ease-out",
          }}
        >
          <div
            className={`flex ${isDragging ? "" : "animate-marquee"}`}
            style={{
              animationDirection: direction === 1 ? "normal" : "reverse",
              animationDuration: `${speed}s`,
              animationPlayState: isDragging ? "paused" : undefined,
            }}
          >
            {/* First set of logos */}
            {logos.map((logo, index) => (
              <span key={`first-${logo.alt}-${index}`} className="flex items-center shrink-0">
                <span className="mx-8 md:mx-16 flex items-center justify-center">
                  <Image
                    src={logo.src}
                    alt={logo.alt}
                    width={logo.size === "large" ? 350 : 200}
                    height={logo.size === "large" ? 175 : 100}
                    className={`w-auto object-contain pointer-events-none ${
                      logo.size === "large" ? "h-28 md:h-44" : "h-16 md:h-24"
                    }`}
                    style={{ maxWidth: logo.size === "large" ? "350px" : "220px" }}
                    draggable={false}
                  />
                </span>
                <span className="w-2 h-2 md:w-3 md:h-3 bg-neo-accent block rounded-full shrink-0" />
              </span>
            ))}
          </div>
          {/* Duplicate for seamless loop */}
          <div
            className={`flex ${isDragging ? "" : "animate-marquee"}`}
            aria-hidden="true"
            style={{
              animationDirection: direction === 1 ? "normal" : "reverse",
              animationDuration: `${speed}s`,
              animationPlayState: isDragging ? "paused" : undefined,
            }}
          >
            {logos.map((logo, index) => (
              <span key={`second-${logo.alt}-${index}`} className="flex items-center shrink-0">
                <span className="mx-8 md:mx-16 flex items-center justify-center">
                  <Image
                    src={logo.src}
                    alt={logo.alt}
                    width={logo.size === "large" ? 350 : 200}
                    height={logo.size === "large" ? 175 : 100}
                    className={`w-auto object-contain pointer-events-none ${
                      logo.size === "large" ? "h-28 md:h-44" : "h-16 md:h-24"
                    }`}
                    style={{ maxWidth: logo.size === "large" ? "350px" : "220px" }}
                    draggable={false}
                  />
                </span>
                <span className="w-2 h-2 md:w-3 md:h-3 bg-neo-accent block rounded-full shrink-0" />
              </span>
            ))}
          </div>
        </div>
      </div>
    );
  }

  // Original text mode
  const displayItems = items?.length ? items : [""];

  return (
    <div
      ref={containerRef}
      className="relative flex overflow-hidden border-y-4 border-neo-border bg-neo-surface py-4 select-none cursor-grab active:cursor-grabbing"
      onMouseDown={handleMouseDown}
      onMouseMove={handleMouseMove}
      onMouseUp={handleDragEnd}
      onMouseLeave={handleDragEnd}
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleDragEnd}
    >
      <div
        className="flex"
        style={{
          transform: `translateX(${dragOffset}px)`,
          transition: isDragging ? "none" : "transform 0.3s ease-out",
        }}
      >
        <div
          className={`flex ${isDragging ? "" : "animate-marquee"} font-black text-4xl md:text-8xl uppercase tracking-tighter text-neo-text`}
          style={{
            animationDirection: direction === 1 ? "normal" : "reverse",
            animationDuration: `${speed}s`,
            animationPlayState: isDragging ? "paused" : undefined,
          }}
        >
          {displayItems.map((item, index) => (
            <span key={`first-${item}-${index}`} className="flex items-center shrink-0">
              <span className="mx-4 md:mx-8 whitespace-nowrap">{item}</span>
              <span className="w-4 h-4 md:w-8 md:h-8 bg-neo-accent block rounded-full shrink-0" />
            </span>
          ))}
        </div>
        {/* Duplicate for seamless loop */}
        <div
          className={`flex ${isDragging ? "" : "animate-marquee"} font-black text-4xl md:text-8xl uppercase tracking-tighter text-neo-text`}
          aria-hidden="true"
          style={{
            animationDirection: direction === 1 ? "normal" : "reverse",
            animationDuration: `${speed}s`,
            animationPlayState: isDragging ? "paused" : undefined,
          }}
        >
          {displayItems.map((item, index) => (
            <span key={`second-${item}-${index}`} className="flex items-center shrink-0">
              <span className="mx-4 md:mx-8 whitespace-nowrap">{item}</span>
              <span className="w-4 h-4 md:w-8 md:h-8 bg-neo-accent block rounded-full shrink-0" />
