"use client";

import React, { useRef, useState, useCallback, useEffect } from "react";
import Image from "next/image";

interface FilmImage {
  src: string;
  alt: string;
}

interface FilmBannerProps {
  images?: FilmImage[];
  speed?: number;
  pauseOnHover?: boolean;
}

// Film collages data
const filmCollages: FilmImage[] = [
  {
    src: "/img/films/collage-2022.jpg",
    alt: "Productions 2022 - America, I Want You Back, Magic for Humans, Divorce, Trust Me",
  },
  {
    src: "/img/films/collage-2023.png",
    alt: "Productions 2023 - Skandal, Shaq, Queen of Oz, Mr Inbetween, Evil, Firefly Lane",
  },
  {
    src: "/img/films/collage-2024.png",
    alt: "Productions 2024 - L'Agence, Maternelles, Project Icon, Trafficked, Tattoo Cover",
  },
  {
    src: "/img/films/collage-2025.png",
    alt: "Productions 2025 - Notes of Berlin, Mother Undercover, Mysteries of the Abandoned",
  },
];

export const FilmBanner: React.FC<FilmBannerProps> = ({
  images = filmCollages,
  speed = 18,
  pauseOnHover = true,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [startX, setStartX] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);
  const [dragOffset, setDragOffset] = useState(0);

  // Handle mouse down
  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    setIsDragging(true);
    setStartX(e.pageX);
    setScrollLeft(dragOffset);
  }, [dragOffset]);

  // Handle touch start
  const handleTouchStart = useCallback((e: React.TouchEvent) => {
    setIsDragging(true);
    setStartX(e.touches[0].pageX);
    setScrollLeft(dragOffset);
  }, [dragOffset]);

  // Handle mouse move
  const handleMouseMove = useCallback((e: React.MouseEvent) => {
    if (!isDragging) return;
    e.preventDefault();
    const x = e.pageX;
    const walk = (x - startX) * 2; // Multiply for faster scrolling
    setDragOffset(scrollLeft + walk);
  }, [isDragging, startX, scrollLeft]);

  // Handle touch move
  const handleTouchMove = useCallback((e: React.TouchEvent) => {
    if (!isDragging) return;
    const x = e.touches[0].pageX;
    const walk = (x - startX) * 2;
    setDragOffset(scrollLeft + walk);
  }, [isDragging, startX, scrollLeft]);

  // Handle mouse up / touch end
  const handleDragEnd = useCallback(() => {
    setIsDragging(false);
  }, []);

  // Global mouse up listener
  useEffect(() => {
    const handleGlobalMouseUp = () => {
      if (isDragging) {
        setIsDragging(false);
      }
    };

    window.addEventListener("mouseup", handleGlobalMouseUp);
    window.addEventListener("touchend", handleGlobalMouseUp);

    return () => {
      window.removeEventListener("mouseup", handleGlobalMouseUp);
      window.removeEventListener("touchend", handleGlobalMouseUp);
    };
  }, [isDragging]);

  const renderImages = (keyPrefix: string, showAlt: boolean = true) =>
    images.map((img, idx) => (
      <div
        key={`${keyPrefix}-${idx}`}
        className="h-[180px] md:h-[280px] lg:h-[350px] flex-shrink-0"
      >
        <Image
          src={img.src}
          alt={showAlt ? img.alt : ""}
          width={900}
          height={350}
          className="h-full w-auto object-cover pointer-events-none"
          draggable={false}
          priority={idx < 2 && showAlt}
        />
      </div>
    ));

  return (
    <section className="overflow-hidden bg-neo-bg border-y-4 border-neo-border">
      <div
        ref={containerRef}
        className={`${pauseOnHover ? "group" : ""} cursor-grab active:cursor-grabbing`}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleDragEnd}
        onMouseLeave={handleDragEnd}
        onTouchStart={handleTouchStart}
        onTouchMove={handleTouchMove}
        onTouchEnd={handleDragEnd}
      >
        <div
          className="flex"
          style={{
            transform: `translateX(${dragOffset}px)`,
            transition: isDragging ? "none" : "transform 0.3s ease-out",
          }}
        >
          {/* First set */}
          <div
            className={`flex ${isDragging ? "" : "animate-marquee"} ${
              pauseOnHover && !isDragging ? "group-hover:[animation-play-state:paused]" : ""
            }`}
            style={{
              animationDuration: `${speed}s`,
              animationDirection: "reverse",
              animationPlayState: isDragging ? "paused" : undefined,
            }}
          >
            {renderImages("first", true)}
          </div>
          {/* Duplicate for seamless loop */}
          <div
            className={`flex ${isDragging ? "" : "animate-marquee"} ${
              pauseOnHover && !isDragging ? "group-hover:[animation-play-state:paused]" : ""
            }`}
            aria-hidden="true"
            style={{
              animationDuration: `${speed}s`,
              animationDirection: "reverse",
              animationPlayState: isDragging ? "paused" : undefined,
            }}
          >
            {renderImages("dup", false)}
          </div>
        </div>
      </div>
    </section>
  );
};

export default FilmBanner;

